"""Project Doppelganger: Multi-Route Tape Selector

NOT derived from a top competitor's replays -- an earlier attempt to extract
Ryo Hasegawa's strategy via per-step consensus voting across multiple real
replays was built and abandoned (see project_doppelganger/build_consensus_tapes.py,
extract_master_ryo_tapes.py) because averaging independent games' actions
step-by-step produces a spatially incoherent tape (each game's hand position
at step N depends on that game's own path; voting the "most common" action
across different games' positions doesn't correspond to a walkable sequence).

What actually ships here is three of our own previously-validated tapes
(tape_165k_straw_cow.json, tape_151k.json, and Aegis's
_ACTIONS_6C12S_4Q_FIRST_YARN) behind a day-3 shop-signal route selector,
locked once chosen -- the route is decided the first time real shop data
exists and never re-evaluated, since re-checking every step let the route
flip mid-game as more shops accumulated later (confirmed: 15/39 seeds
switched tapes mid-game before this fix, including a genuine day-12 switch
between two spatially unrelated tapes). Wrapped in a safe-fallback exception
handler.
"""

import base64
import json
import zlib
from typing import Dict, List, Any

_FIB = [1, 1]
while len(_FIB) < 30:
    _FIB.append(_FIB[-1] + _FIB[-2])


def _hire_cost_total(n_hires: int) -> float:
    return float(sum(_FIB[:n_hires]))


def _todays_capex(action: Dict[str, Any]) -> float:
    """Fibonacci hire cost plus any other capex the tape schedules this step.
    Root cause this guards against: hands wipe nightly, so the tape re-hires
    its full crew every morning at Fibonacci cost (1,1,2,3,5,8,13...). As the
    crew grows, that daily cost eventually exceeds available cash on some day;
    that day's hires silently fail (engine: `if money < cost: return`), hands
    stay at 0 for the whole day, production stops, and money never recovers
    enough to re-hire the full crew again -- a permanent death spiral.
    Confirmed empirically: one real seed collapsed from a $150k+ trajectory to
    a $25k final score this way."""
    n_hires = sum(1 for o in (action.get("market") or []) if isinstance(o, list) and len(o) > 0 and o[0] == "HIRE")
    capex = _hire_cost_total(n_hires)
    animal_cost = {"COW": 400.0, "SHEEP": 500.0, "GOOSE": 300.0}
    seed_cost = {"WHEAT": 10.0, "CARROT": 20.0, "TOMATO": 50.0, "STRAWBERRY": 100.0, "MELON": 80.0}
    for o in (action.get("market") or []):
        if not (isinstance(o, list) and len(o) > 0):
            continue
        if o[0] == "BUY_ANIMAL" and len(o) >= 2:
            n = int(o[2]) if len(o) >= 3 and str(o[2]).isdigit() else 1
            capex += animal_cost.get(o[1], 400.0) * n
        elif o[0] == "BUY_SEED" and len(o) >= 2:
            n = int(o[2]) if len(o) >= 3 and str(o[2]).isdigit() else 1
            capex += seed_cost.get(o[1], 20.0) * n
        elif o[0] == "BUY_PRODUCT" and len(o) >= 2:
            n = int(o[2]) if len(o) >= 3 and str(o[2]).isdigit() else 1
            capex += 25.0 * n
    return capex


def _ensure_liquidity(obs: Dict[str, Any], action: Dict[str, Any]) -> Dict[str, Any]:
    player = obs.get("player", 0)
    farms = obs.get("farms", [{}, {}])
    my_farm = farms[player] if len(farms) > player else {}
    money = float(my_farm.get("money", 0.0) or 0.0)
    needed = _todays_capex(action)
    if money >= needed:
        return action

    shortfall = needed - money
    shed = (obs.get("private") or {}).get("shed", {}) or {}
    market_prices = (obs.get("market") or {}).get("prices", {}) or {}
    market = action.setdefault("market", [])

    already_selling: Dict[str, int] = {}
    for o in market:
        if isinstance(o, list) and len(o) >= 3 and o[0] == "SELL":
            already_selling[o[1]] = already_selling.get(o[1], 0) + max(0, int(o[2] or 0))

    items_by_price = sorted(shed.keys(), key=lambda it: market_prices.get(it, 0), reverse=True)
    recovered = 0.0
    for item in items_by_price:
        if recovered >= shortfall or len(market) >= 10:
            break
        avail = max(0, int(shed.get(item, 0) or 0) - already_selling.get(item, 0))
        if avail <= 0:
            continue
        unit_p = max(1.0, float(market_prices.get(item, 1)))
        need_units = int((shortfall - recovered + unit_p - 1) // unit_p)
        qty = min(avail, max(1, need_units))
        market.insert(0, ["SELL", item, qty])
        already_selling[item] = already_selling.get(item, 0) + qty
        recovered += qty * unit_p

    action["market"] = market[:10]
    return action

