_ROUTE_LOCK: Dict[int, str] = {}


def _select_route(shops: List[str]) -> str:
    # YARN and DUAL_MELON are both DISABLED as of this build: both suffer from
    # hand-index fragility when replayed through a bare route-selector with no
    # supporting state (hand roles are purely positional in these tapes; once
    # the live hand count ever diverges from what the tape assumes -- which
    # happens by the tape's own design as early as day 3 -- all subsequent
    # hand-to-task assignments permanently misalign). Measured: YARN collapses
    # to a hiring death spiral (~$25k vs a $150k+ trajectory); DUAL_MELON caps
    # consistently around $53-56k across every seed tested. STRAW_COW
    # (tape_165k_straw_cow.json) is the only one of the three confirmed robust
    # across many seeds ($146k-181k) and does not exhibit this issue.
    # Re-enable YARN/DUAL_MELON only after that fragility is actually fixed.
    return "STRAW_COW"


def _agent_impl(obs: Dict[str, Any], config: Any = None) -> Dict[str, Any]:
    step = obs.get("step", 0)
    player = obs.get("player", 0)
    farms = obs.get("farms", [])
    live_hands = len(farms[player].get("hands", [])) if len(farms) > player else 0

    if step == 0:
        _ROUTE_LOCK.pop(player, None)

    town_info = obs.get("town") or {}
    shops = town_info.get("unlocked_shops", []) or []

    # Lock the route the first time real shop data exists (day 3+) and never
    # re-evaluate it again. Re-checking `shops` every step (the original bug)
    # means the route can flip mid-game as more shops accumulate later (e.g.
    # BAKERY+BRUNCH_SPOT crossing the >=2 threshold on day 12) -- switching
    # between _ACTIONS_STRAW_COW/_ACTIONS_DUAL_MELON/_ACTIONS_YARN mid-game is
    # a switch between three unrelated real recorded games with no shared
    # spatial layout, causing the exact desync class documented in
    # MASTER_DOSSIER.md Part 40.3 (the Day 0-3 Spatial Coherence Invariant).
    if player not in _ROUTE_LOCK and len(shops) >= 1:
        _ROUTE_LOCK[player] = _select_route(shops)
    route = _ROUTE_LOCK.get(player, "STRAW_COW")
    active_tape = {"YARN": _ACTIONS_YARN, "DUAL_MELON": _ACTIONS_DUAL_MELON, "STRAW_COW": _ACTIONS_STRAW_COW}[route]

    if step < len(active_tape):
        raw_act = active_tape[step]
        farmer_act = list(raw_act.get("farmer", ["PASS"]))
        hands_act = list(raw_act.get("hands", []))[:live_hands]
        market_act = list(raw_act.get("market", []))[:10]
        while len(hands_act) < live_hands:
            hands_act.append(["PASS"])
        action = {
            "farmer": farmer_act,
            "hands": hands_act,
            "market": market_act
        }
        action = _ensure_liquidity(obs, action)
        action["market"] = action.get("market", [])[:10]
        return action
    return {"farmer": ["PASS"], "hands": [["PASS"]] * live_hands, "market": []}


def agent(obs: Dict[str, Any], config: Any = None) -> Dict[str, Any]:
    try:
        return _agent_impl(obs, config)
    except Exception:
        player = obs.get("player", 0) if isinstance(obs, dict) else 0
        farms = obs.get("farms", []) if isinstance(obs, dict) else []
        me = farms[player] if len(farms) > player and isinstance(farms[player], dict) else {}
        hands_count = len(me.get("hands", []) or [])
        return {"farmer": ["PASS"], "hands": [["PASS"] for _ in range(hands_count)], "market": []}
